package com.intermarche.backoffice.engine.fieldops;
import com.intermarche.backoffice.engine.printing.*;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.printing.*;import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.executing.LoadedTote;import com.intermarche.backoffice.engine.fieldops.*;import com.intermarche.backoffice.engine.operator.OperatorFailure;
import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import java.util.*;
@ApplicationScoped @Transactional public class PrintingService {
 @Inject jakarta.persistence.EntityManager em;@Inject FieldOperationsService field;@Inject StockCommands receipts;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="PrintingInput") public static class Input {public Long storeId,printerId,templateId,subjectId,jobId,expectedRevision;public String requestKey,code,label,transport,host,simulation,kind,title,reason,subjectType;public Integer port,dpi,widthDots,heightDots;public Boolean enabled;}
 private Store store(Input i){if(i==null)throw new BadRequestException();FieldOperationsService.key(i.requestKey);return field.store(i.storeId,true);}
 private StorePrinter printer(Store s,Long key){StorePrinter p=StorePrinter.find("id=?1 and store=?2",key,s).firstResult();if(p==null)throw new NotFoundException();return p;}
 private PrintJob job(Store s,Long key){PrintJob j=PrintJob.<PrintJob>find("id=?1 and store=?2",key,s).withLock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE).firstResult();if(j==null)throw new NotFoundException();return j;}
 public Object configurePrinter(Input i){Store s=store(i);field.requireManager();String fp=field.hash(i);var prior=receipts.previous(s,i.requestKey,fp);if(prior!=null)return receipts.value(prior);boolean fresh=i.printerId==null;var p=fresh?new StorePrinter():printer(s,i.printerId);if(!fresh&&(i.expectedRevision==null||p.revisionNumber!=i.expectedRevision))throw new OperatorFailure(409,"STALE_PRINTER","Actualisez l’imprimante");FieldOperationsService.text(i.code,40);FieldOperationsService.text(i.label,100);if(!i.code.matches("[A-Za-z0-9_-]+"))throw new BadRequestException("Code d’imprimante invalide");if(StorePrinter.count("store=?1 and code=?2 and (?3 is null or id<>?3)",s,i.code,p.id)>0)throw new BadRequestException("Code d’imprimante déjà utilisé");String transport=i.transport==null?"SIMULATOR":i.transport;String simulation=i.simulation==null?"SUCCESS":i.simulation;int port=i.port==null?9100:i.port;try{PrinterTransport.validate(new PrinterTransport.Destination(transport,i.host,port,simulation));}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}if(i.dpi!=null&&!Set.of(203,300).contains(i.dpi))throw new BadRequestException("Résolution requise : 203 ou 300 dpi");p.store=s;p.code=i.code;p.label=i.label;p.transport=transport;p.host=i.host;p.port=port;p.dpi=i.dpi==null?203:i.dpi;p.simulation=simulation;p.enabled=i.enabled==null||i.enabled;p.revisionNumber++;if(fresh)p.persistAndFlush();return receipts.record(s,i.requestKey,fp,"CONFIGURE_PRINTER",printerView(p));}
 public Object createTemplate(Input i){Store s=store(i);field.requireManager();String fp=field.hash(i);var prior=receipts.previous(s,i.requestKey,fp);if(prior!=null)return receipts.value(prior);FieldOperationsService.text(i.code,40);FieldOperationsService.text(i.title,60);if(!Set.of("PARCEL","TOTE","DESTINATION").contains(i.kind==null?"":i.kind))throw new BadRequestException("Type de modèle invalide");var old=LabelTemplate.<LabelTemplate>find("store=?1 and code=?2 order by revisionNumber desc",s,i.code).firstResult();var t=new LabelTemplate();t.store=s;t.code=i.code;t.kind=i.kind;t.title=i.title;t.revisionNumber=old==null?1:old.revisionNumber+1;t.widthDots=i.widthDots==null?812:i.widthDots;t.heightDots=i.heightDots==null?600:i.heightDots;t.createdBy=field.actor();try{LabelRenderer.render("DEMO-123",t.title,List.of("Commande exemple","Destination exemple"),t.widthDots,t.heightDots);}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}t.persistAndFlush();return receipts.record(s,i.requestKey,fp,"CREATE_LABEL_TEMPLATE",templateView(t));}
 record Data(String type,Long id,String code,List<String> lines){}
 /**
  * Returns the data printed on the label of a parcel, a tote, a destination or a carrier tour.
  *
  * @param s the store
  * @param type the subject type
  * @param key the subject id
  * @return the label data
  */
 private Data subject(Store s,String type,Long key){if("PARCEL".equals(type)){Parcel p=Parcel.find("id=?1 and store=?2",key,s).firstResult();if(p==null)throw new NotFoundException();return new Data(type,key,p.code,List.of("Commande "+p.order.orderId,"Emballage "+p.packagingType));}if("PHYSICAL_TOTE".equals(type)){Tote t=Tote.findById(key);if(t==null||!Objects.equals(id(t.store),s.id))throw new NotFoundException();return new Data(type,key,t.code,List.of("Bac "+t.code));}if("TOTE".equals(type)){LoadedTote t=LoadedTote.findById(key);if(t==null||!Objects.equals(id(t.tote.store),s.id))throw new NotFoundException();return new Data(type,key,t.tote.code,List.of("Bac "+t.tote.code,"Conditionnement "+t.storageType));}if("DESTINATION".equals(type)){LogisticsDeparture d=LogisticsDeparture.find("id=?1 and store=?2",key,s).firstResult();if(d==null)throw new NotFoundException();return new Data(type,key,d.destinationCode,List.of("Commande "+d.order.orderId,"Référence "+d.transportReference,"Destinataire "+d.recipient));}if("TOUR".equals(type)){DepartureTour t=DepartureTour.find("id=?1 and store=?2",key,s).firstResult();if(t==null)throw new NotFoundException();return new Data(type,key,t.code,List.of(t.serviceLevel.carrier.name+" · "+t.serviceLevel.label,"Quai "+t.dock.code+" · départ "+t.plannedDeparture.toLocalTime(),t.sealNumber==null?"Plomb à poser":"Plomb "+t.sealNumber,LogisticsDeparture.count("tour",t)+" commande(s)"));}throw new BadRequestException("Sujet d’étiquette invalide");}
 private LabelTemplate template(Store s,Input i){if(i.templateId==null)return null;LabelTemplate t=LabelTemplate.find("id=?1 and store=?2",i.templateId,s).firstResult();if(t==null)throw new NotFoundException();if(!t.kind.equals("PHYSICAL_TOTE".equals(i.subjectType)?"TOTE":i.subjectType))throw new BadRequestException("Modèle incompatible");return t;}
 /**
  * Renders a label with its template, or the standard layout of its subject type.
  *
  * @param data the label data
  * @param t the template, or null
  * @return the rendered label
  */
 private LabelRenderer.Rendered render(Data data,LabelTemplate t){try{return LabelRenderer.render(data.code,t==null?switch(data.type){case"TOTE","PHYSICAL_TOTE"->"Bac";case"PARCEL"->"Colis";case"TOUR"->"Tournée";default->"Destination";}:t.title,data.lines,t==null?812:t.widthDots,t==null?600:t.heightDots);}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}}
 public Object preview(Long storeId,String type,Long subjectId,Long templateId){Store s=field.store(storeId,false);var i=new Input();i.subjectType=type;i.templateId=templateId;var data=subject(s,type,subjectId);var rendered=render(data,template(s,i));return Map.of("code",data.code,"preview",rendered.preview());}
 private String payloadHash(String payload){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public Object enqueue(Input i){Store s=store(i);String fp=field.hash(i);var prior=receipts.previous(s,i.requestKey,fp);if(prior!=null)return receipts.value(prior);var printer=printer(s,i.printerId);if(!printer.enabled)throw new BadRequestException("Imprimante désactivée");var j=new PrintJob();j.store=s;j.printer=printer;j.frozenDestination=field.encode(new PrinterTransport.Destination(printer.transport,printer.host,printer.port,printer.simulation));j.requestedBy=field.actor();if(i.jobId!=null){var source=job(s,i.jobId);FieldOperationsService.text(i.reason,255);if(!Set.of("SENT","FAILED","UNKNOWN","CANCELLED").contains(source.state))throw new OperatorFailure(409,"PRINT_STILL_ACTIVE","Attendez ou annulez le travail actif avant de le réimprimer");j.reprintOf=source;j.reason=i.reason;j.subjectId=source.subjectId;j.subjectType=source.subjectType;j.logisticsCode=source.logisticsCode;j.template=source.template;j.templateVersion=source.templateVersion;j.frozenData=source.frozenData;j.frozenPayload=source.frozenPayload;j.frozenPreview=source.frozenPreview;j.payloadSha256=source.payloadSha256;}else{Data data=subject(s,i.subjectType,i.subjectId);if(PrintJob.count("store=?1 and subjectType=?2 and subjectId=?3",s,i.subjectType,i.subjectId)>0)throw new OperatorFailure(409,"LABEL_ALREADY_REQUESTED","Une étiquette existe déjà. Consultez son travail puis réimprimez avec un motif.");var template=template(s,i);var rendered=render(data,template);j.subjectId=data.id;j.subjectType=data.type;j.logisticsCode=data.code;j.template=template;j.templateVersion=template==null?1:template.revisionNumber;j.frozenData=field.encode(Map.of("code",data.code,"lines",data.lines));j.frozenPayload=rendered.payload();j.frozenPreview=rendered.preview();j.payloadSha256=payloadHash(j.frozenPayload);}j.persistAndFlush();return receipts.record(s,i.requestKey,fp,"ENQUEUE_LABEL",jobView(j));}
 public Object cancel(Input i){Store s=store(i);String fp=field.hash(i);var prior=receipts.previous(s,i.requestKey,fp);if(prior!=null)return receipts.value(prior);var j=job(s,i.jobId);if(!j.requestedBy.equals(field.actor()))field.requireManager();if(i.expectedRevision==null||j.revisionNumber!=i.expectedRevision||!"QUEUED".equals(j.state))throw new OperatorFailure(409,"PRINT_PHASE_CHANGED","Seul un travail encore en attente peut être annulé");FieldOperationsService.text(i.reason,255);j.state="CANCELLED";j.reason=i.reason;j.revisionNumber++;return receipts.record(s,i.requestKey,fp,"CANCEL_LABEL",jobView(j));}
 public Object probe(Long storeId,Long printerId){var s=field.store(storeId,false);var p=printer(s,printerId);if(!p.enabled)return Map.of("state","DISABLED","detail","Imprimante désactivée");if("SIMULATOR".equals(p.transport))return Map.of("state","SIMULATED","detail","Imprimante simulée ; aucune connexion physique");var destination=new PrinterTransport.Destination(p.transport,p.host,p.port,p.simulation);try{var address=PrinterTransport.validate(destination,PrinterTransport.Policy.configured());try(var socket=new java.net.Socket()){socket.connect(new java.net.InetSocketAddress(address,p.port),1500);}return Map.of("state","REACHABLE","detail","Connexion réseau accessible ; papier et sortie physique non vérifiés");}catch(Exception failure){return Map.of("state","DISCONNECTED","detail","Imprimante inaccessible. Vérifiez son alimentation et sa connexion réseau");}}
 public Object configuration(Long storeId){Store s=field.store(storeId,false);return Map.of("printers",StorePrinter.<StorePrinter>list("store=?1 order by code",s).stream().map(this::printerView).toList(),"templates",LabelTemplate.<LabelTemplate>find("store=?1 order by code,revisionNumber desc",s).range(0,199).list().stream().map(this::templateView).toList(),"canManage",field.manager());}
 public Object list(Long storeId,long before,int limit){Store s=field.store(storeId,false);if(limit<1||limit>100||before<0)throw new BadRequestException();var rows=PrintJob.<PrintJob>find("select j from PrintJob j join fetch j.printer where j.store=?1 and (?2=0 or j.id<?2) order by j.id desc",s,before).range(0,limit).list();return Map.of("items",rows.stream().limit(limit).map(this::summary).toList(),"hasMore",rows.size()>limit,"nextBefore",rows.isEmpty()?before:rows.get(Math.min(rows.size(),limit)-1).id);}
 public Object lastJob(Long storeId,String type,Long subjectId){Store s=field.store(storeId,false);subject(s,type,subjectId);PrintJob j=PrintJob.find("store=?1 and subjectType=?2 and subjectId=?3 order by id desc",s,type,subjectId).firstResult();return j==null?Map.of("exists",false):Map.of("exists",true,"job",jobView(j));}
 public Object read(Long storeId,Long key){return jobView(job(field.store(storeId,false),key));}
 private Map<String,Object> printerView(StorePrinter p){var v=new LinkedHashMap<String,Object>();v.put("id",p.id);v.put("code",p.code);v.put("label",p.label);v.put("transport",p.transport);v.put("host",p.host);v.put("port",p.port);v.put("dpi",p.dpi);v.put("simulation",p.simulation);v.put("enabled",p.enabled);v.put("revision",p.revisionNumber);return v;}
 private Map<String,Object> templateView(LabelTemplate t){return Map.of("id",t.id,"code",t.code,"kind",t.kind,"title",t.title,"revision",t.revisionNumber,"widthDots",t.widthDots,"heightDots",t.heightDots);}
 private Map<String,Object> summary(PrintJob j){var v=new LinkedHashMap<String,Object>();v.put("id",j.id);v.put("state",j.state);v.put("revision",j.revisionNumber);v.put("code",j.logisticsCode);v.put("subjectType",j.subjectType);v.put("subjectId",j.subjectId);v.put("printer",j.printer.label);v.put("printerId",id(j.printer));v.put("simulated","SIMULATOR".equals(field.decode(j.frozenDestination,PrinterTransport.Destination.class).transport()));v.put("templateVersion",j.templateVersion);v.put("attemptCount",j.attemptCount);v.put("requestedBy",j.requestedBy);v.put("createdAt",j.createdAt);v.put("sentAt",j.sentAt);v.put("lastError",j.lastError);v.put("reason",j.reason);v.put("reprintOf",j.reprintOf==null?null:id(j.reprintOf));return v;}
 private Map<String,Object> jobView(PrintJob j){var v=summary(j);v.put("preview",j.frozenPreview);v.put("payloadSha256",j.payloadSha256);v.put("attempts",PrintAttempt.<PrintAttempt>list("job=?1 order by attemptNumber",j).stream().map(a->{var r=new LinkedHashMap<String,Object>();r.put("number",a.attemptNumber);r.put("state",a.state);r.put("error",a.errorCode);r.put("startedAt",a.startedAt);r.put("completedAt",a.completedAt);return r;}).toList());return v;}
}
